#!/usr/bin/env bash
# Lints the IR of the whole compiler: rc2-norepl, generated by the rc2 in
# rc2/build/exec, dumped with --directive dumprcexpr and checked by this
# tool. The test suite (rc2/tests/verify.sh) only lints each test's dump,
# so a shape that only a program this size has goes unchecked there.
#
# Usage: tools/rcexpr-lint/selfcheck.sh [WORKDIR]
#
# WORKDIR (default: rc2/tests/build/selfcheck) gets a copy of
# rc2/src_norepl and the build; it is emptied first. Needs rc2 built and
# installed (rc2-norepl.ipkg depends on the installed rc2 package), and
# a shell that has sourced env.sh. Exit code: the lint's.
set -euo pipefail

TOOL_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$TOOL_DIR/../.." && pwd)"
RC2="$REPO_ROOT/rc2"
WORK="${1:-$RC2/tests/build/selfcheck}"

(cd "$TOOL_DIR" && idris2 --build rcexpr-lint.ipkg) > /dev/null
rm -rf "${WORK:?}"
mkdir -p "$WORK"
cp -r "$RC2/src_norepl" "$RC2/rc2-norepl.ipkg" "$WORK/"
(cd "$WORK" && "$RC2/build/exec/idris2-rc2" --cg rc2 --directive nocc --directive dumprcexpr --build rc2-norepl.ipkg) > "$WORK/build.log" 2>&1 \
    || { echo "selfcheck: rc2-norepl did not build, see $WORK/build.log"; exit 2; }
"$TOOL_DIR/build/exec/rcexpr-lint" "$WORK/build/exec/idris2-rc2-norepl.rcexpr" | grep -v '^ \|^metrics'
